            "title": "财务术语与关系",
            "excerpt": "{\n  \"domain\": \"财务\",\n  \"terms\": [\n    {\n      \"termId\": \"t11\",\n      \"name\": \"账户\",\n      \"definition\": \"记录现金、银行或线上资金余额及变动的结算对象。\",\n      \"domain\": \"财务\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t29\",\n      \"name\": \"收款\",\n      \"definition\": \"从客户或其他付款方取得资金并登记结算的业务动作。\",\n      \"domain\": \"财务\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t30\",\n      \"name\": \"付款\",\n      \"definition\": \"向供应商或其他收款方支付资金并登记结算的业务动作。\",\n      \"domain\": \"财务\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t31\",\n      \"name\": \"订金\",\n      \"definition\": \"在正式结算前由客户或业务方预先支付的金额。\",\n      \"domain\": \"财务\",\n      \"aliases\": [\n        \"预付款\"\n      ]\n    },\n    {\n      \"termId\": \"t32\",\n      \"name\": \"应收\",\n      \"definition\": \"经营单位根据销售或其他业务应向对方收取的金额。\",\n      \"domain\": \"财务\",\n      \"aliases\": [\n        \"应收款\"\n      ]\n    },\n    {\n      \"termId\": \"t33\",\n      \"name\": \"应付\",\n      \"definition\": \"经营单位根据采购或其他业务应向对方支付的金额。\",\n      \"domain\": \"财务\",\n      \"aliases\": [\n        \"应付款\"\n      ]\n    },\n    {\n      \"termId\": \"t34\",\n      \"name\": \"欠款\",\n      \"definition\": \"应结金额扣除已收、已付和可抵扣金额后形成的未结余额。\",\n      \"domain\": \"财务\",\n      \"aliases\": [\n        \"未结余额\"\n      ]\n    },\n    {\n      \"termId\": \"t35\",\n      \"name\": \"结算\",\n      \"definition\": \"确认业务金额、资金变动和双方余额的财务处理过程。\",\n      \"domain\": \"财务\",\n      \"aliases\": []\n    }\n  ],\n  \"relations\": [\n    {\n      \"relationId\": \"r27\",\n      \"subjectId\": \"t29\",\n      \"predicate\": \"改变\",\n      \"objectId\": \"t11\",\n      \"description\": \"收款会改变结算账户余额。\",\n      \"subjectName\": \"收款\",\n      \"objectName\": \"账户\"\n    },\n    {\n      \"relationId\": \"r28\",\n      \"subjectId\": \"t30\",\n      \"predicate\": \"改变\",\n      \"objectId\": \"t11\",\n      \"description\": \"付款会改变结算账户余额。\",\n      \"subjectName\": \"付款\",\n      \"objectName\": \"账户\"\n    },\n    {\n      \"relationId\": \"r29\",\n      \"subjectId\": \"t31\",\n      \"predicate\": \"抵扣\",\n      \"objectId\": \"t34\",\n      \"description\": \"订金可以抵扣后续欠款。\",\n      \"subjectName\": \"订金\",\n      \"objectName\": \"欠款\"\n    },\n    {\n      \"relationId\": \"r30\",\n      \"subjectId\": \"t32\",\n      \"predicate\": \"形成\",\n      \"objectId\": \"t34\",\n      \"description\": \"未收应收可能形成欠款。\",\n      \"subjectName\": \"应收\",\n      \"objectName\": \"欠款\"\n    },\n    {\n      \"relationId\": \"r31\",\n      \"subjectId\": \"t33\",\n      \"predicate\": \"形成\",\n      \"objectId\": \"t34\",\n      \"description\": \"未付应付可能形成欠款。\",\n      \"subjectName\": \"应付\",\n      \"objectName\": \"欠款\"\n    },\n    {\n      \"relationId\": \"r32\",\n      \"subjectId\": \"t34\",\n      \"predicate\": \"属于\",\n      \"objectId\": \"t35\",\n      \"description\": \"欠款是结算过程中需要确认的余额。\",\n      \"subjectName\": \"欠款\",\n      \"objectName\": \"结算\"\n    },\n    {\n      \"relationId\": \"r69\",\n      \"subjectId\": \"t14\",\n      \"predicate\": \"产生\",\n      \"objectId\": \"t33\",\n      \"description\": \"采购入库可能产生应付金额。\",\n      \"subjectName\": \"采购入库\",\n      \"objectName\": \"应付\"\n    },\n    {\n      \"relationId\": \"r70\",\n      \"subjectId\": \"t17\",\n      \"predicate\": \"产生\",\n      \"objectId\": \"t32\",\n      \"description\": \"销售出库可能产生应收金额。\",\n      \"subjectName\": \"销售出库\",\n      \"objectName\": \"应收\"\n    },\n    {\n      \"relationId\": \"r71\",\n      \"subjectId\": \"t29\",\n      \"predicate\": \"减少\",\n      \"objectId\": \"t32\",\n      \"description\": \"收款减少客户应收余额。\",\n      \"subjectName\": \"收款\",\n      \"objectName\": \"应收\"\n    },\n    {\n      \"relationId\": \"r72\",\n      \"subjectId\": \"t30\",\n      \"predicate\": \"减少\",\n      \"objectId\": \"t33\",\n      \"description\": \"付款减少供应商应付余额。\",\n      \"subjectName\": \"付款\",\n      \"objectName\": \"应付\"\n    }\n  ]\n}\n",
