            "excerpt": "{\n  \"domain\": \"报表指标\",\n  \"terms\": [\n    {\n      \"termId\": \"t36\",\n      \"name\": \"采购统计\",\n      \"definition\": \"按采购入库等业务事件汇总采购数量和金额的报表。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t37\",\n      \"name\": \"销售统计\",\n      \"definition\": \"按销售出库等业务事件汇总销售数量和金额的报表。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t38\",\n      \"name\": \"库存报表\",\n      \"definition\": \"展示库存期初、流入、流出、期末和金额的报表。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t39\",\n      \"name\": \"业务日期\",\n      \"definition\": \"表示采购、销售、收货或发货实际发生时间的统计日期。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": [\n        \"发生时间\"\n      ]\n    },\n    {\n      \"termId\": \"t40\",\n      \"name\": \"结存数量\",\n      \"definition\": \"在指定时间点商品经过流入流出后的数量余额。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": [\n        \"期末数量\"\n      ]\n    },\n    {\n      \"termId\": \"t41\",\n      \"name\": \"结存金额\",\n      \"definition\": \"按确定的计价口径计算的库存数量对应金额。\",\n      \"domain\": \"报表指标\",\n      \"aliases\": []\n    }\n  ],\n  \"relations\": [\n    {\n      \"relationId\": \"r33\",\n      \"subjectId\": \"t14\",\n      \"predicate\": \"进入\",\n      \"objectId\": \"t36\",\n      \"description\": \"采购入库是采购统计的重要业务事件。\",\n      \"subjectName\": \"采购入库\",\n      \"objectName\": \"采购统计\"\n    },\n    {\n      \"relationId\": \"r34\",\n      \"subjectId\": \"t17\",\n      \"predicate\": \"进入\",\n      \"objectId\": \"t37\",\n      \"description\": \"销售出库是销售统计的重要业务事件。\",\n      \"subjectName\": \"销售出库\",\n      \"objectName\": \"销售统计\"\n    },\n    {\n      \"relationId\": \"r35\",\n      \"subjectId\": \"t21\",\n      \"predicate\": \"展示于\",\n      \"objectId\": \"t38\",\n      \"description\": \"当前库存进入库存报表。\",\n      \"subjectName\": \"当前库存\",\n      \"objectName\": \"库存报表\"\n    },\n    {\n      \"relationId\": \"r36\",\n      \"subjectId\": \"t39\",\n      \"predicate\": \"确定\",\n      \"objectId\": \"t40\",\n      \"description\": \"业务日期帮助确定指定时点的结存数量。\",\n      \"subjectName\": \"业务日期\",\n      \"objectName\": \"结存数量\"\n    },\n    {\n      \"relationId\": \"r37\",\n      \"subjectId\": \"t40\",\n      \"predicate\": \"计算\",\n      \"objectId\": \"t41\",\n      \"description\": \"结存数量结合计价口径形成结存金额。\",\n      \"subjectName\": \"结存数量\",\n      \"objectName\": \"结存金额\"\n    },\n    {\n      \"relationId\": \"r73\",\n      \"subjectId\": \"t38\",\n      \"predicate\": \"使用\",\n      \"objectId\": \"t39\",\n      \"description\": \"库存报表使用业务日期筛选期间。\",\n      \"subjectName\": \"库存报表\",\n      \"objectName\": \"业务日期\"\n    },\n    {\n      \"relationId\": \"r74\",\n      \"subjectId\": \"t36\",\n      \"predicate\": \"汇总\",\n      \"objectId\": \"t14\",\n      \"description\": \"采购统计汇总采购入库数量和金额。\",\n      \"subjectName\": \"采购统计\",\n      \"objectName\": \"采购入库\"\n    },\n    {\n      \"relationId\": \"r75\",\n      \"subjectId\": \"t37\",\n      \"predicate\": \"汇总\",\n      \"objectId\": \"t17\",\n      \"description\": \"销售统计汇总销售出库数量和金额。\",\n      \"subjectName\": \"销售统计\",\n      \"objectName\": \"销售出库\"\n    },\n    {\n      \"relationId\": \"r76\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"决定\",\n      \"objectId\": \"t36\",\n      \"description\": \"审核口径影响采购统计是否纳入单据。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"采购统计\"\n    },\n    {\n      \"relationId\": \"r77\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"决定\",\n      \"objectId\": \"t37\",\n      \"description\": \"审核口径影响销售统计是否纳入单据。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"销售统计\"\n    }\n  ]\n}\n",
