            "excerpt": "{\n  \"domain\": \"工作流审计\",\n  \"terms\": [\n    {\n      \"termId\": \"t48\",\n      \"name\": \"审核\",\n      \"definition\": \"由有权人员确认单据内容、业务责任和后续处理条件的动作。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": [\n        \"审批\"\n      ]\n    },\n    {\n      \"termId\": \"t49\",\n      \"name\": \"反审核\",\n      \"definition\": \"在检查后续影响后撤销审核结论并允许重新处理的动作。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": [\n        \"撤销审核\"\n      ]\n    },\n    {\n      \"termId\": \"t50\",\n      \"name\": \"审核中\",\n      \"definition\": \"单据已提交但尚未完成全部审核环节的工作流状态。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": [\n        \"状态九\"\n      ]\n    },\n    {\n      \"termId\": \"t51\",\n      \"name\": \"完成度\",\n      \"definition\": \"表示采购、销售或其他后续业务已完成比例的业务状态。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": [\n        \"部分完成\"\n      ]\n    },\n    {\n      \"termId\": \"t52\",\n      \"name\": \"审计记录\",\n      \"definition\": \"记录制单、审核、反审核、变更和异常处理过程的信息。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t53\",\n      \"name\": \"关联单据\",\n      \"definition\": \"通过来源关系连接申请、订单、出入库和退货的单据集合。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": []\n    },\n    {\n      \"termId\": \"t54\",\n      \"name\": \"多级审核\",\n      \"definition\": \"按照预设层级由多名责任人依次确认单据的审批方式。\",\n      \"domain\": \"工作流审计\",\n      \"aliases\": []\n    }\n  ],\n  \"relations\": [\n    {\n      \"relationId\": \"r40\",\n      \"subjectId\": \"t43\",\n      \"predicate\": \"承担\",\n      \"objectId\": \"t48\",\n      \"description\": \"用户可以承担制单或审核责任。\",\n      \"subjectName\": \"用户\",\n      \"objectName\": \"审核\"\n    },\n    {\n      \"relationId\": \"r44\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"改变\",\n      \"objectId\": \"t50\",\n      \"description\": \"提交审核可能使单据进入审核中。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"审核中\"\n    },\n    {\n      \"relationId\": \"r45\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"确认\",\n      \"objectId\": \"t51\",\n      \"description\": \"审核会确认单据是否具备后续处理条件。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"完成度\"\n    },\n    {\n      \"relationId\": \"r46\",\n      \"subjectId\": \"t49\",\n      \"predicate\": \"撤销\",\n      \"objectId\": \"t48\",\n      \"description\": \"反审核撤销既有审核结论。\",\n      \"subjectName\": \"反审核\",\n      \"objectName\": \"审核\"\n    },\n    {\n      \"relationId\": \"r47\",\n      \"subjectId\": \"t50\",\n      \"predicate\": \"属于\",\n      \"objectId\": \"t54\",\n      \"description\": \"审核中可能是多级审核的中间阶段。\",\n      \"subjectName\": \"审核中\",\n      \"objectName\": \"多级审核\"\n    },\n    {\n      \"relationId\": \"r48\",\n      \"subjectId\": \"t52\",\n      \"predicate\": \"记录\",\n      \"objectId\": \"t48\",\n      \"description\": \"审计记录保存审核动作和责任信息。\",\n      \"subjectName\": \"审计记录\",\n      \"objectName\": \"审核\"\n    },\n    {\n      \"relationId\": \"r49\",\n      \"subjectId\": \"t52\",\n      \"predicate\": \"记录\",\n      \"objectId\": \"t49\",\n      \"description\": \"审计记录保存反审核原因和结果。\",\n      \"subjectName\": \"审计记录\",\n      \"objectName\": \"反审核\"\n    },\n    {\n      \"relationId\": \"r50\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t12\",\n      \"description\": \"关联单据可以连接请购来源。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"请购\"\n    },\n    {\n      \"relationId\": \"r51\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t13\",\n      \"description\": \"关联单据可以连接采购订单。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"采购订单\"\n    },\n    {\n      \"relationId\": \"r52\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t14\",\n      \"description\": \"关联单据可以连接采购入库。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"采购入库\"\n    },\n    {\n      \"relationId\": \"r53\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t15\",\n      \"description\": \"关联单据可以连接采购退货。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"采购退货\"\n    },\n    {\n      \"relationId\": \"r54\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t16\",\n      \"description\": \"关联单据可以连接销售订单。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"销售订单\"\n    },\n    {\n      \"relationId\": \"r55\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t17\",\n      \"description\": \"关联单据可以连接销售出库。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"销售出库\"\n    },\n    {\n      \"relationId\": \"r56\",\n      \"subjectId\": \"t53\",\n      \"predicate\": \"连接\",\n      \"objectId\": \"t18\",\n      \"description\": \"关联单据可以连接销售退货。\",\n      \"subjectName\": \"关联单据\",\n      \"objectName\": \"销售退货\"\n    },\n    {\n      \"relationId\": \"r76\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"决定\",\n      \"objectId\": \"t36\",\n      \"description\": \"审核口径影响采购统计是否纳入单据。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"采购统计\"\n    },\n    {\n      \"relationId\": \"r77\",\n      \"subjectId\": \"t48\",\n      \"predicate\": \"决定\",\n      \"objectId\": \"t37\",\n      \"description\": \"审核口径影响销售统计是否纳入单据。\",\n      \"subjectName\": \"审核\",\n      \"objectName\": \"销售统计\"\n    },\n    {\n      \"relationId\": \"r78\",\n      \"subjectId\": \"t54\",\n      \"predicate\": \"包含\",\n      \"objectId\": \"t48\",\n      \"description\": \"多级审核包含多个责任人的审核动作。\",\n      \"subjectName\": \"多级审核\",\n      \"objectName\": \"审核\"\n    }\n  ]\n}\n",
